pub enum Limit {
    Value(u32),
    Unlimited,
}

impl Limit {
    pub fn default_agent_steps() -> Self { Self::Value(12) }
    pub fn default_step_actions() -> Self { Self::Value(20) }
    pub fn default_minutes(value: u32) -> Self { Self::Value(value) }
    pub fn is_reached_by(&self, value: u32) -> bool {
        match self {
            Self::Value(limit) => value >= *limit,
            Self::Unlimited => false,
        }
    }
}

fn limit_reached(limit: &Limit, count: u32) -> bool {
    limit.is_reached_by(count)
}

