fn record_event_with_group(
    &mut self,
    run_id: Option<String>,
    group_id: Option<String>,
    step_id: Option<String>,
    kind: &str,
    payload: serde_json::Value,
    display: impl Into<String>,
) -> Result<()> {
    let event = HistoryEvent::new_with_group(
        self.history.session_id().to_string(),
        run_id, group_id, step_id, kind, payload,
    );
    self.history.append_event(&event)?;
    if self.debug_enabled { self.history.append_debug_event(&event)?; }
    self.chat_projection.apply_history_event(&event);
    self.sync_chat_items();
    self.state.events.push(display.into());
    self.publish_state();
    Ok(())
}

pub fn apply_history_event(&mut self, event: &HistoryEvent) {
    match event.kind.as_str() {
        "session_started" | "session_ended" => {}
        "run_started" => self.apply_run_started(event),
        "prompt_submitted" => self.apply_user_prompt(event),
        "clarification_requested" => self.apply_clarification_requested(event),
        "clarification_answered" => self.apply_clarification_answered(event),
        "orchestrator_decision" => self.apply_orchestrator_decision(event),
        // ... action/command/file/approval arms ...
        "run_completed" | "run_failed" | "run_limit_reached" | "run_interrupted"
        | "subtask_completed" => self.apply_run_summary(event),
        "diagnostic" => self.apply_diagnostic(event),
        // council events fall here -> apply_diagnostic (lifecycle_key: None, NO collapse):
        "config_viewed" | "session_goal_viewed" | ... 
        | "council_started"
        | "council_synthesized"
        | "council_completed"
        | ... | "orchestrator_decision_invalid" => self.apply_diagnostic(event),
        _ => {}
    }
}

