        summary: input.summary.map(|s| concise(&s, MAX_SUMMARY_CHARS)),
        body: bounded_body(input.body), details: input.details,
        source: input.source, updated_at: input.updated_at };
    if let Some(key) = lifecycle_key {
        if let Some(index) = self.index.get(&key).copied() {
            let existing = &mut self.items[index];
            let mut source = item.source;
            for event_id in &existing.source.event_ids { source.merge_event(event_id); }
            *existing = ChatItemView { source, ..item };
            if is_terminal_run_conclusion(&self.items[index], &key) {
                let concluded = self.items.remove(index);
                self.items.push(concluded);
                self.rebuild_index();
            }
            return;
        }
        self.index.insert(key, self.items.len());
    }
    self.items.push(item);
}

const MAX_BODY_LINES: usize = 12;

fn bounded_body(body: Vec<ChatLineView>) -> Vec<ChatLineView> {
    body.into_iter()
        .take(MAX_BODY_LINES)
        .map(|mut line| { line.text = concise(&line.text, MAX_SUMMARY_CHARS); line })
        .collect()
}

fn is_terminal_run_conclusion(item: &ChatItemView, key: &ChatLifecycleKey) -> bool {
    matches!(key, ChatLifecycleKey::Run { .. } | ChatLifecycleKey::Workflow { .. })
        && item.kind == ChatItemKind::RunSummary
        && matches!(item.status,
            ChatItemStatus::Completed | ChatItemStatus::Failed | ChatItemStatus::Interrupted)
}

fn apply_clarification_answered(&mut self, event: &HistoryEvent) {
    let answer = string_field(&event.payload, "answer").unwrap_or_else(|| "No answer provided.".to_string());
    let lifecycle_key = clarification_key(event);
    // READ the prior item's body to recover the question text:
    let question = lifecycle_key.as_ref()
        .and_then(|key| self.index.get(key).copied())
        .and_then(|index| self.items.get(index))
        .and_then(|item| item.body.first())
        .map(|line| line.text.clone());
    let mut body = Vec::new();
    if let Some(question) = question { body.push(ChatLineView::muted(format!("Question: {question}"))); }
    body.push(ChatLineView::plain(format!("Answer: {answer}")));
    // ... appends Option:/Custom answer lines by answer_source ...
    self.upsert(ItemInput {
        lifecycle_key, kind: ChatItemKind::Clarification, status: ChatItemStatus::Completed,
        severity: ChatSeverity::Info, title: "Clarifying question answered".to_string(),
        summary: Some(concise(&answer, MAX_SUMMARY_CHARS)), body,
        details: history_detail(event, "history"), source: source_from_event(event, None),
        updated_at: event.timestamp.clone(), fallback_event_id: event.event_id.clone(),
    });
}

fn apply_diagnostic(&mut self, event: &HistoryEvent) {
    // ...
    self.upsert(ItemInput {
        lifecycle_key: None,            // <- no key => a NEW item every event, never collapses
        kind: ChatItemKind::Diagnostic,
        status: if is_error { ChatItemStatus::Failed } else { ChatItemStatus::Completed },
        // ...
    });
}

